import XCTest
@testable import PokeTokenBar

/// An expedition under way and the last result as this build saves them (2026-11-04). An update that cannot read them
/// back drops the expedition: the keys or the Treasure Map, the berries and Revives taken from the Bag, the challenge's try
/// and the tokens walked are gone (`DungeonProgress` decodes it leniently, to nil). A field added to `Expedition`,
/// `BattlerSpec`, `BattleSetup`, `ExpeditionLogEntry` or `ExpeditionResult` must decode without its key: Optional, or read
/// with a default. This test fails otherwise.
final class DungeonSaveFormatTests: XCTestCase {
    func testAnExpeditionSavedByThisBuildIsReadBack() throws {
        let progress = try JSONDecoder().decode(DungeonProgress.self, from: Data(Self.saved.utf8))
        let e = try XCTUnwrap(progress.expedition, "the expedition under way is read back")
        XCTAssertEqual(e.dungeon, .viridianForest)
        XCTAssertEqual(e.team.count, 3)
        XCTAssertTrue(e.log.contains { if case .battle = $0.kind { return true } else { return false } }, "its battle too")
        let result = try XCTUnwrap(progress.lastResult, "and the last result")
        XCTAssertTrue(result.won)
    }

